import os,shutil,subprocess
from pathlib import Path
paths=[Path('/root/.claude-server-commander/puppeteer-cache'),Path('/home/ubuntu/.claude-server-commander/puppeteer-cache')]
def sysstate(name):
 p=subprocess.run(['systemctl','is-active',name+'.service'],capture_output=True,text=True,timeout=8)
 return p.stdout.strip()
def pmstatus():
 p=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=13)
 if p.returncode:raise RuntimeError('PM2 inaccessible')
 import json
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(p.stdout)}
services=['pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-root','nginx','postgresql@16-main']
baseline={k:sysstate(k) for k in services}
if any(v!='active' for v in baseline.values()):raise RuntimeError('Baseline service inactive')
bots=pmstatus()
if bots.get('iptvpn_bot')!='online' or bots.get('telegram-robot-leads')!='online':raise RuntimeError('Telegram bot not online')
existing=[]
for path in paths:
 if not path.is_dir() or path.is_symlink():
  raise RuntimeError('Unexpected cache state: '+str(path))
 if path.name!='puppeteer-cache' or path.parent.name!='.claude-server-commander':
  raise RuntimeError('Path allowlist not respected')
 if path.parent.is_symlink():raise RuntimeError('Unexpected parent symlink')
 for proc in Path('/proc').iterdir():
  if not proc.name.isdigit():continue
  try:
   cwd=os.readlink(proc/'cwd')
   exe=os.readlink(proc/'exe')
   if cwd==str(path) or cwd.startswith(str(path)+'/') or exe.startswith(str(path)+'/'):
    raise RuntimeError('Active process uses cache')
  except OSError:pass
  try:
   for fd in (proc/'fd').iterdir():
    try:
     link=os.readlink(fd)
     if link==str(path) or link.startswith(str(path)+'/'):
      raise RuntimeError('Active file handle uses cache')
    except OSError:pass
  except OSError:pass
 v=subprocess.run(['du','-x','-s','-B1',str(path)],capture_output=True,text=True,timeout=50)
 if v.returncode:raise RuntimeError('Cannot measure '+str(path))
 existing.append((path,int(v.stdout.split()[0])))
print('CACHE_CANDIDATES_BYTES='+str(sum(s for _,s in existing)))
before=shutil.disk_usage('/').free
for path,s in existing:
 shutil.rmtree(path)
 print('CLEANED='+str(path)+'|BYTES='+str(s))
for path,s in existing:
 if path.exists() or path.is_symlink():raise RuntimeError('Cache still present')
free=shutil.disk_usage('/').free
print('DISK_FREE_GAIN_BYTES='+str(free-before))
for name in services:
 now=sysstate(name)
 print('SERVICE|'+name+'|'+now)
 if now!=baseline[name]:raise RuntimeError('Protected service status changed')
post=pmstatus()
for name in ('iptvpn_bot','telegram-robot-leads'):
 print('BOT|'+name+'|'+str(post.get(name)))
 if post.get(name)!='online':raise RuntimeError('Bot not online')
print('FERRARI_PRESENT='+str(Path('/home/ubuntu/.local/share/motor-ferrari').is_dir()))
print('REA_FINAL_PRESENT='+str(Path('/home/ubuntu/rea-final-runtime').is_dir()))
print('CLAUDE_PUPPETEER_CACHE_CLEANUP=PASS')
PY
